  var graph = normalizeGraph(account.graph);
  var elements = graph.map(function (el) {
    var data = el.data || el;
    var out = { data: Object.assign({}, data) };
    if (!out.data.label) out.data.label = shortId(data.name || data.id);
    return out;
  });

  var nodeIds = {};
  elements.forEach(function (el) { if (el.data.id) nodeIds[el.data.id] = el; });

  var sensitiveIds = {};
  (report.sensitive_resources || []).forEach(function (r) { sensitiveIds[r.id] = true; });

  var unionNodes = {}, unionEdges = {};
  paths.forEach(function (path) {
    (path.nodes || []).forEach(function (id) { unionNodes[id] = true; });
    (path.hops || []).forEach(function (hop) {
      var key = edgeKey(hop.source, hop.target);
      unionEdges[key] = true;
      edgeEvidence[key] = hop;
      var edgeElement = elements.filter(function (el) {
        return el.data.source === hop.source && el.data.target === hop.target;
      })[0];
      if (edgeElement) edgeElement.data.label = hop.port || "";
    });
