const path = require('path');
const { JSDOM } = require('jsdom');
const cytoscape = require('cytoscape');

const REPO = '/home/dev/feedback/uid38834';
const html = fs.readFileSync(path.join(REPO, 'web/reachability.html'), 'utf8');

const dom = new JSDOM(html, { runScripts: 'outside-only', pretendToBeVisual: true });
const { window } = dom;

// Permissive canvas 2d context stub so cytoscape can boot under jsdom.
function makeCtx() {
  return new Proxy({}, {
    get(t, prop) {
      if (prop === 'measureText') return () => ({ width: 40 });
      if (prop === 'canvas') return { width: 800, height: 600 };
      if (prop in t) return t[prop];
      return () => {};
    },
    set(t, prop, value) { t[prop] = value; return true; }
  });
}
window.HTMLCanvasElement.prototype.getContext = function () { return makeCtx(); };

global.window = window;
global.document = window.document;
global.navigator = window.navigator;
global.HTMLElement = window.HTMLElement;
global.Node = window.Node;
global.Event = window.Event;
global.FileReader = window.FileReader;
global.cytoscape = cytoscape;
global.fetch = () => Promise.resolve({
  ok: true,
  json: () => Promise.resolve(JSON.parse(fs.readFileSync(path.join(REPO, 'web/reachability-demo.json'), 'utf8')))
});

const code = fs.readFileSync(path.join(REPO, 'web/js/reachability-view.js'), 'utf8');
window.eval(code);

setTimeout(() => {
  try {
    const options = document.querySelectorAll('#accountSelect option');
    const cards = document.querySelectorAll('.path-card');
    console.log('account options:', options.length);
    console.log('path cards:', cards.length);
    if (options.length !== 3) throw new Error('expected 3 account options');
    if (cards.length !== 2) throw new Error('expected 2 cards for first account');
    cards[0].click();
    console.log('clicked first card OK');
    // switch account
    const sel = document.getElementById('accountSelect');
    sel.value = '1';
    sel.dispatchEvent new window.Event('change');
    setTimeout(() => {
      const cards2 = document.querySelectorAll('.path-card');
      console.log('analytics cards:', cards2.length);
      if (cards2.length !== 2) { console.error('FAIL'); process.exit(1); }
      cards2[1].click();
      console.log('SMOKE OK');
      process.exit(0);
    }, 50);
  } catch (e) {
    console.error('SMOKE FAIL', e);
    process.exit(1);
  }
}, 300);
EOF
